import asyncio, json
R="us-east-1"
LB_ARN="arn:aws:elasticloadbalancing:us-east-1:776638915601:loadbalancer/app/umami-acse705bbf9/6ab8bc1a4ce11519"

async def safe(**kw):
    try:
        return await call_boto3(**kw)
    except Exception as e:
        return {"__error__": str(e)}

async def main():
    tags, listeners, tgs, stacks, clusters = await asyncio.gather(
        safe(service_name="elbv2", operation_name="DescribeTags", region_name=R, params={"ResourceArns":[LB_ARN]}),
        safe(service_name="elbv2", operation_name="DescribeListeners", region_name=R, params={"LoadBalancerArn":LB_ARN}),
        safe(service_name="elbv2", operation_name="DescribeTargetGroups", region_name=R),
        safe(service_name="cloudformation", operation_name="DescribeStacks", region_name=R),
        safe(service_name="ecs", operation_name="ListClusters", region_name=R),
        return_exceptions=True,
    )
    out = {"lb_tags": tags, "listeners": listeners}
    out["target_groups"] = [
        {k: tg.get(k) for k in ("TargetGroupName","TargetGroupArn","LoadBalancerArns","VpcId","Port","TargetType")}
        for tg in tgs.get("TargetGroups", [])
    ]
    out["stacks"] = [
        {"StackName": s.get("StackName"), "StackStatus": s.get("StackStatus"), "CreationTime": str(s.get("CreationTime")),
         "Tags": s.get("Tags")}
        for s in stacks.get("Stacks", [])
    ]
    out["ecs_clusters"] = clusters.get("clusterArns", [])
    return out

result = await main()
result

import asyncio
R="us-east-1"
async def safe(tag, **kw):
    try:
        return (tag, await call_boto3(**kw))
    except Exception as e:
        return (tag, f"ERR {e}")

async def main():
    out = {}
    out["delete_cluster"] = (await safe("c", service_name="ecs", operation_name="DeleteCluster", region_name=R,
                                        params={"cluster":"umami-acse705bbf9"}))[1]
    out["delete_taskdefs"] = (await safe("td", service_name="ecs", operation_name="DeleteTaskDefinitions", region_name=R,
        params={"taskDefinitions":["arn:aws:ecs:us-east-1:776638915601:task-definition/umami-acse705bbf9:1",
                                   "arn:aws:ecs:us-east-1:776638915601:task-definition/umami-acse705bbf9:2"]}))[1]
    # IAM role cleanup
    role="umami-acse705bbf9-exec"
    att = await safe("att", service_name="iam", operation_name="ListAttachedRolePolicies", params={"RoleName":role})
    inl = await safe("inl", service_name="iam", operation_name="ListRolePolicies", params={"RoleName":role})
    out["attached"] = att[1] if isinstance(att[1],str) else att[1].get("AttachedPolicies")
    out["inline"] = inl[1] if isinstance(inl[1],str) else inl[1].get("PolicyNames")
    if not isinstance(att[1], str):
        for p in att[1].get("AttachedPolicies", []):
            await safe("d", service_name="iam", operation_name="DetachRolePolicy", params={"RoleName":role,"PolicyArn":p["PolicyArn"]})
    if not isinstance(inl[1], str):
        for pn in inl[1].get("PolicyNames", []):
            await safe("d", service_name="iam", operation_name="DeleteRolePolicy", params={"RoleName":role,"PolicyName":pn})
    out["delete_role"] = (await safe("r", service_name="iam", operation_name="DeleteRole", params={"RoleName":role}))[1]
    return out

